        assertThat(outcomes.stream().filter(o -> o == Outcome.CONFLICT).count())
                .isEqualTo(contenders - 1);

        // 最终该区段只有一张计划的时隙生效
        List<PublishedSlotView> slots = service.getPublishedSlots(DAY, section);
        assertThat(slots).hasSize(1);
    }

